def safe_int(text):
    if text.isdigit():
        return int(text)
    return -1

for value in ["42", "4 2", "abc", ""]:
    print(repr(value), safe_int(value))

def valid_ipv4(address):
    parts = address.split(".")
    if len(parts) != 4:
        return False
    for part in parts:
        if not part.isdigit() or int(part) > 255:
            return False
    return True

print(valid_ipv4("192.168.1.20"), valid_ipv4("192.168.1.256"))
print(valid_ipv4("10.0.1"))

