history = [("A", True)] * 9 + [("A", False)] + [("B", True)] + [("B", False)] * 9
for group in ("A", "B"):
    approved = 0
    total = 0
    for g, ok in history:
        if g == group:
            total = total + 1
            if ok:
                approved = approved + 1
    print(group, approved / total)

urgent_words = ["urgent", "verify", "password", "suspended"]

def risk(email_text):
    score = 0
    for word in urgent_words:
        if word in email_text.lower():
            score = score + 1
    return score

print(risk)
print(risk("Lesson moved to 4pm on Tuesday"))

def shift(text, key):
    result = ""
    for ch in text:
        if ch.isalpha():
            result = result + chr((ord(ch) - 65 + key) % 26 + 65)
        else:
            result = result + ch
    return result

secret = shift("MEET AT FAJR", 3)
print(secret)
print(shift(secret, -3))
